<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { toast } from 'vue-sonner';
import DefinitionPage from '../../components/shared/DefinitionPage.vue';
import DefinitionDialog from '../../components/shared/DefinitionDialog.vue';
import { listCampaignsV2, listSponsorCollections, listSponsorContributions, createSponsorCollection,
  calculateSponsorContribution, updateSponsorContribution } from '../../services/dooh';
import { humanError } from '../../services/api';
const records = ref([]), contributions = ref([]), campaigns = ref([]), loading = ref(false), error = ref(''), search = ref('');
const open = ref(false), saving = ref(false), formError = ref(''), contribution = ref(null);
const today = () => new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Istanbul' }).format(new Date());
const empty = () => ({ campaign: '', brut_tutar: '', tahsilat_tarihi: today(), donem_baslangic: '', donem_bitis: '', yontem: 'HAVALE', referans: '' });
const form = reactive(empty());
const invoice = reactive({ eczane_fatura_no: '', eczane_fatura_teblig_tarihi: '', odenme_tarihi: '' });
const filtered = computed(() => records.value.filter(row => `${row.campaign_ad} ${row.referans}`.toLocaleLowerCase('tr').includes(search.value.toLocaleLowerCase('tr'))));
const money = value => Number(value).toLocaleString('tr-TR', { minimumFractionDigits: 2 }) + ' TL';
async function load() { loading.value = true; error.value = ''; try { const [r, c, h] = await Promise.all([listSponsorCollections(), listCampaignsV2(), listSponsorContributions()]); const rows = res => Array.isArray(res.data) ? res.data : res.data.results || []; records.value = rows(r); campaigns.value = rows(c); contributions.value = rows(h); } catch (e) { error.value = humanError(e); } finally { loading.value = false; } }
function create() { Object.assign(form, empty()); formError.value = ''; open.value = true; }
async function save() { saving.value = true; formError.value = ''; try { await createSponsorCollection({ ...form }); open.value = false; toast.success('Tahsilat kaydedildi.'); await load(); } catch (e) { formError.value = humanError(e); } finally { saving.value = false; } }
async function calculate(row) { saving.value = true; try { const { data } = await calculateSponsorContribution(row.id); toast.success(`${data.length} eczanenin katkı hesabı kaydedildi.`); await load(); } catch (e) { toast.error(humanError(e)); } finally { saving.value = false; } }
function editInvoice(row) { contribution.value = row; Object.assign(invoice, { eczane_fatura_no: row.eczane_fatura_no || '', eczane_fatura_teblig_tarihi: row.eczane_fatura_teblig_tarihi || '', odenme_tarihi: row.odenme_tarihi || '' }); formError.value = ''; }
async function saveInvoice() { saving.value = true; try { await updateSponsorContribution(contribution.value.id, { ...invoice, eczane_fatura_teblig_tarihi: invoice.eczane_fatura_teblig_tarihi || null, odenme_tarihi: invoice.odenme_tarihi || null, durum: invoice.odenme_tarihi ? 'ODENDI' : contribution.value.durum }); contribution.value = null; await load(); toast.success('Fatura ve ödeme bilgileri kaydedildi.'); } catch (e) { formError.value = humanError(e); } finally { saving.value = false; } }
onMounted(load);
</script>
<template>
  <DefinitionPage v-model:search="search" title="Sponsor Tahsilatları" description="Fiili tahsilatları ve eczanelere ödenecek katkı paylarını takip edin." :count="filtered.length" :loading="loading" :error="error" new-label="Tahsilat Kaydet" @create="create" @refresh="load">
    <div v-if="filtered.length" class="eisa-table-wrap"><table class="eisa-table"><thead><tr><th>Kampanya</th><th>Dönem</th><th>Tahsilat</th><th>Katkı hesabı</th><th>İşlem</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td><span class="eisa-record-name">{{ row.campaign_ad }}</span><span class="eisa-record-detail">{{ row.referans || 'Referans girilmedi' }}</span></td><td>{{ row.donem_baslangic }} – {{ row.donem_bitis }}</td><td><span class="eisa-record-name">{{ money(row.brut_tutar) }}</span><span class="eisa-record-detail">{{ row.tahsilat_tarihi }}</span></td><td><span class="eisa-pill" :class="row.hesaplanma_tarihi || row.hakedis_sayisi ? 'eisa-pill-success' : 'eisa-pill-muted'">{{ row.hesaplanma_tarihi || row.hakedis_sayisi ? 'Hesaplandı' : 'Hesap bekliyor' }}</span></td><td><div class="eisa-table-actions"><button class="eisa-btn eisa-btn-ghost eisa-btn--sm" :disabled="saving || !!row.hesaplanma_tarihi || !!row.hakedis_sayisi" @click="calculate(row)">Katkıyı hesapla</button></div></td></tr></tbody></table></div>
    <div v-else class="eisa-definition-empty"><i class="fa-solid fa-building-columns"></i><strong>Henüz sponsor tahsilatı yok</strong><span>Katkı hesabı, fiilen alınan tahsilatın %15’i üzerinden oluşur.</span></div>
    <template #extra><section class="eisa-panel eisa-definition-extra"><header class="eisa-panel-header"><h2 class="eisa-panel-title">Eczane Katkı Payları</h2><span class="eisa-record-count">{{ contributions.length }} kayıt</span></header><div v-if="contributions.length" class="eisa-table-wrap"><table class="eisa-table"><thead><tr><th>Eczane / Kampanya</th><th>Cihaz-gün</th><th>Katkı payı</th><th>Ödeme vadesi</th><th>İşlem</th></tr></thead><tbody><tr v-for="row in contributions" :key="row.id"><td><span class="eisa-record-name">{{ row.eczane_ad }}</span><span class="eisa-record-detail">{{ row.campaign_ad }}</span></td><td>{{ row.uygun_cihaz_gun }} / {{ row.toplam_uygun_cihaz_gun }}</td><td>{{ money(row.brut_pay) }}</td><td>{{ row.odeme_son_tarihi || 'Fatura bekleniyor' }}</td><td><div class="eisa-table-actions"><button class="eisa-icon-btn" :disabled="!!row.odenme_tarihi" title="Fatura ve ödeme bilgileri" aria-label="Fatura ve ödeme bilgileri" @click="editInvoice(row)"><i class="fa-solid fa-file-invoice"></i></button></div></td></tr></tbody></table></div><div v-else class="eisa-definition-empty"><span>Hesaplanmış katkı payı bulunmuyor.</span></div></section></template>
    <template #dialogs>
      <DefinitionDialog :open="open" title="Sponsor Tahsilatı Kaydet" :busy="saving" :error="formError" @close="open = false" @save="save"><div class="eisa-form-grid">
        <label class="eisa-form-row eisa-form-row-full"><span class="eisa-field-label">Kampanya *</span><select v-model="form.campaign" class="eisa-field" required><option value="">Kampanya seçin</option><option v-for="campaign in campaigns" :key="campaign.id" :value="campaign.id">{{ campaign.name }}</option></select></label>
        <label class="eisa-form-row"><span class="eisa-field-label">Brüt tahsilat (TL) *</span><input v-model="form.brut_tutar" type="number" min="0.01" step="0.01" class="eisa-field" required /></label><label class="eisa-form-row"><span class="eisa-field-label">Tahsilat tarihi *</span><input v-model="form.tahsilat_tarihi" type="date" :max="today()" class="eisa-field" required /></label>
        <label class="eisa-form-row"><span class="eisa-field-label">Dönem başlangıcı *</span><input v-model="form.donem_baslangic" type="date" class="eisa-field" required /></label><label class="eisa-form-row"><span class="eisa-field-label">Dönem bitişi *</span><input v-model="form.donem_bitis" type="date" class="eisa-field" required /></label>
        <label class="eisa-form-row"><span class="eisa-field-label">Yöntem</span><select v-model="form.yontem" class="eisa-field"><option value="HAVALE">Havale / EFT</option><option value="KART">Kart</option><option value="DIGER">Diğer</option></select></label><label class="eisa-form-row"><span class="eisa-field-label">Banka / dekont referansı</span><input v-model.trim="form.referans" class="eisa-field" /></label>
      </div></DefinitionDialog>
      <DefinitionDialog :open="!!contribution" :title="`${contribution?.eczane_ad || ''} — Fatura ve Ödeme`" :busy="saving" :error="formError" @close="contribution = null" @save="saveInvoice"><div class="eisa-form-grid"><label class="eisa-form-row eisa-form-row-full"><span class="eisa-field-label">Eczane fatura numarası</span><input v-model.trim="invoice.eczane_fatura_no" class="eisa-field" /></label><label class="eisa-form-row"><span class="eisa-field-label">Fatura tebliğ tarihi</span><input v-model="invoice.eczane_fatura_teblig_tarihi" type="date" class="eisa-field" /></label><label class="eisa-form-row"><span class="eisa-field-label">Fiili ödeme tarihi</span><input v-model="invoice.odenme_tarihi" type="date" class="eisa-field" /></label></div><span class="eisa-form-note">Ödeme vadesi tebliğ tarihinden 15 takvim günü sonrasıdır.</span></DefinitionDialog>
    </template>
  </DefinitionPage>
</template>
